import cv2
import base64
from selenium.webdriver.common.action_chains import ActionChains
import time
import random
from PIL import Image
import io
import logging
import uuid
import tempfile

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class ImageUtil:

    @staticmethod
    def get_distance(bgBase64, qkBase64, top):
        save_dir = tempfile.gettempdir()
        slide_bg_file_name = save_dir + "\\" + uuid.uuid4().hex + "_bg.png"
        slide_block_file_name = save_dir + "\\" + uuid.uuid4().hex + "_qk.png"
        ImageUtil.convert_base64_to_image(bgBase64.replace("data:image/jpg;base64,", ""), slide_bg_file_name)
        ImageUtil.convert_base64_to_image(qkBase64.replace("data:image/png;base64,", ""), slide_block_file_name)

        # 读取图像文件
        bg_img = Image.open(slide_bg_file_name)
        slide_img = Image.open(slide_block_file_name)

        # 裁剪背景图像
        # 获取滑块图像的宽度和高度
        slide_width, slide_height = slide_img.size

        bg_cropped = bg_img.crop((slide_width, top, bg_img.width - slide_width, top + slide_height))
        # 保存裁剪后的图像（可选）
        bg_cropped.save(slide_bg_file_name)

        # 读取图像
        bg_img = cv2.imread(slide_bg_file_name)
        slide_img = cv2.imread(slide_block_file_name)


        # 转灰度图像
        slide_gray = cv2.cvtColor(slide_img, cv2.COLOR_BGR2GRAY)
        bg_gray = cv2.cvtColor(bg_img, cv2.COLOR_BGR2GRAY)

        # 二值化图像
        _, slide_bin = cv2.threshold(slide_gray, 127, 255, cv2.THRESH_BINARY)
        _, bg_bin = cv2.threshold(bg_gray, 127, 255, cv2.THRESH_BINARY)

        # 轮廓图
        slide_edges = cv2.Canny(slide_bin, 50, 150)
        bg_edges = cv2.Canny(bg_bin, 50, 150)

        # 模板匹配
        result = cv2.matchTemplate(bg_edges, slide_edges, cv2.TM_CCOEFF_NORMED)
        _, max_val, _, max_loc = cv2.minMaxLoc(result)

        # 计算匹配位置
        match_location = max_loc[0] + slide_img.shape[1]
        offset = 4
        if match_location > 250:
            offset += 2

        return match_location + offset

    @staticmethod
    def convert_base64_to_image(base64_str, path):
        image_bytes = base64.b64decode(base64_str)
        try:
            image = Image.open(io.BytesIO(image_bytes))
            image.save(path, 'PNG')
        except Exception as e:
            logger.error("convertBase64ToImage", e)
            raise Exception("图片转换失败")

# 示例用法
if __name__ == "__main__":
    qkBase64 = "data:image/jpg;base64,"
    bgBase64 = "data:image/png;base64,";
    top = 121
    distance = ImageUtil.get_distance(qkBase64, bgBase64, top)
    # 206
    print(distance)
